Here is the Python function implementing Dijkstra's algorithm to find the shortest path based on your requirements. 

It uses the `heapq` module for efficiency and includes checks for negative edge weights and unreachable destinations.

```python
import heapq

def shortest_path(edges, start, end):
    # Base case: if start and end are the same node
    if start == end:
        return (0, [start])

    # Build the adjacency list and check for negative weights
    graph = {}
    for u, v, weight in edges:
        if weight < 0:
            raise ValueError("Edge weights cannot be negative.")
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []  # Ensure end nodes are in the graph keys
        graph[u].append((v, weight))

    # If start node isn't in the graph, no path exists
    if start not in graph:
        return (None, None)

    # Priority queue stores: (current_distance, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Track visited nodes to avoid processing the same node multiple times with a longer distance
    visited = set()

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # If we reached the destination, return the distance and path
        if current_node == end:
            return (current_distance, path)

        if current_node in visited:
            continue
        visited.add(current_node)

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                if neighbor not in visited:
                    heapq.heappush(pq, (current_distance + weight, neighbor, path + [neighbor]))

    # If the priority queue is exhausted and we haven't returned, no path exists
    return (None, None)
```

### Example Usage:

```python
# Example 1: Standard case
edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]
print(shortest_path(edges, "A", "C"))  
# Output: (3, ['A', 'B', 'C'])

# Example 2: Start and end are the same
print(shortest_path(edges, "A", "A"))  
# Output: (0, ['A'])

# Example 3: No path exists
print(shortest_path(edges, "C", "A"))  
# Output: (None, None)

# Example 4: Negative weight (raises ValueError)
try:
    shortest_path([("A", "B", -1)], "A", "B")
except ValueError as e:
    print(e)  
# Output: Edge weights cannot be negative.
```

